"""Metric layer (contract R5 / R7).

Token level: all test tokens of all test documents are pooled into a single ranking (micro),
which is what the authors' Demo.ipynb does (roc_auc_score(y_test, scores) over the flattened
test tokens).  Document level: Eq. (3), the arithmetic mean of the token scores of a document.
"""
import numpy as np
from sklearn.metrics import average_precision_score, roc_auc_score


def auroc(y_true, scores):
    y_true = np.asarray(y_true)
    scores = np.asarray(scores, dtype=np.float64)
    if len(np.unique(y_true)) < 2:
        return float("nan")
    return float(roc_auc_score(y_true, scores))


def auprc(y_true, scores):
    y_true = np.asarray(y_true)
    scores = np.asarray(scores, dtype=np.float64)
    if y_true.sum() == 0:
        return float("nan")
    return float(average_precision_score(y_true, scores))


def token_metrics(y_true, scores):
    return {"auroc": auroc(y_true, scores), "auprc": auprc(y_true, scores)}


def document_scores(scores, doc_index, n_docs=None):
    """Eq. (3): mean of the token-level scores inside each document."""
    scores = np.asarray(scores, dtype=np.float64)
    doc_index = np.asarray(doc_index)
    if n_docs is None:
        n_docs = int(doc_index.max()) + 1
    out = np.full(n_docs, np.nan)
    for d in range(n_docs):
        m = doc_index == d
        if m.any():
            out[d] = scores[m].mean()
    return out


def document_metrics(doc_scores, doc_labels):
    doc_scores = np.asarray(doc_scores, dtype=np.float64)
    ok = np.isfinite(doc_scores)
    return {"auroc": auroc(np.asarray(doc_labels)[ok], doc_scores[ok]),
            "auprc": auprc(np.asarray(doc_labels)[ok], doc_scores[ok])}


def random_control(y_true, doc_index, doc_labels, seed=0):
    rng = np.random.RandomState(seed)
    s = rng.rand(len(y_true))
    tok = token_metrics(y_true, s)
    doc = document_metrics(document_scores(s, doc_index), doc_labels)
    return {"token": tok, "doc": doc}


def self_check():
    """Verify the metric plumbing on synthetic data (plan: 'Metric parity')."""
    rng = np.random.RandomState(0)
    y = rng.binomial(1, 0.2, size=500)
    s = y + rng.randn(500) * 0.5
    assert abs(auroc(y, s) - roc_auc_score(y, s)) < 1e-12
    assert abs(auprc(y, s) - average_precision_score(y, s)) < 1e-12
    perfect = auroc(y, y.astype(float))
    assert abs(perfect - 1.0) < 1e-12, perfect
    ds = document_scores(np.array([1.0, 3.0, 5.0, 7.0]), np.array([0, 0, 1, 1]))
    assert np.allclose(ds, [2.0, 6.0]), ds
    return True

